-- Source: sql/analysis/10_analytical_views.sql
{{ config(materialized='view') }}

SELECT
  g.segment_type,
  g.segment_name,
  g.retail_year,
  g.period,
  g.sales_lines,
  g.units_sold,
  g.transactions,
  g.gross_sales,
  g.discount_value,
  g.sales_revenue,
  g.returns_value,
  g.net_revenue,
  g.cogs,
  g.gross_margin,
  g.promo_sales_revenue,
  g.target_net_revenue,
  CAST(g.sales_revenue AS DOUBLE) / NULLIF(CAST(g.transactions AS DOUBLE), 0) AS aov,
  CAST(g.units_sold AS DOUBLE) / NULLIF(CAST(g.transactions AS DOUBLE), 0) AS upt,
  CAST(g.sales_revenue AS DOUBLE) / NULLIF(CAST(g.units_sold AS DOUBLE), 0) AS asp,
  CAST(g.gross_margin AS DOUBLE) / NULLIF(CAST(g.net_revenue AS DOUBLE), 0) AS gross_margin_pct,
  CAST(g.returns_value AS DOUBLE) / NULLIF(CAST(g.sales_revenue AS DOUBLE), 0) AS return_rate_value,
  CAST(g.promo_sales_revenue AS DOUBLE) / NULLIF(CAST(g.sales_revenue AS DOUBLE), 0) AS promo_revenue_share,
  CAST(g.net_revenue AS DOUBLE) / NULLIF(CAST(g.target_net_revenue AS DOUBLE), 0) AS target_achievement_pct
FROM (
  SELECT
    u.segment_type,
    u.segment_name,
    u.retail_year,
    u.period,
    SUM(u.sales_lines) AS sales_lines,
    SUM(u.units_sold) AS units_sold,
    SUM(u.transactions) AS transactions,
    SUM(u.gross_sales) AS gross_sales,
    SUM(u.discount_value) AS discount_value,
    SUM(u.sales_revenue) AS sales_revenue,
    SUM(u.returns_value) AS returns_value,
    SUM(u.net_revenue) AS net_revenue,
    SUM(u.cogs) AS cogs,
    SUM(u.gross_margin) AS gross_margin,
    SUM(u.promo_sales_revenue) AS promo_sales_revenue,
    SUM(u.target_net_revenue) AS target_net_revenue
  FROM (
    SELECT
      N'Estate' AS segment_type,
      N'Brightwater estate' AS segment_name,
      s.*
    FROM {{ ref('v_kpi_store_period') }} AS s
    UNION ALL
    SELECT
      N'Region',
      s.region,
      s.*
    FROM {{ ref('v_kpi_store_period') }} AS s
    UNION ALL
    SELECT
      N'Format',
      s.store_format,
      s.*
    FROM {{ ref('v_kpi_store_period') }} AS s
    UNION ALL
    SELECT
      N'Store',
      CONCAT(s.store_id, N' ', s.store_name),
      s.*
    FROM {{ ref('v_kpi_store_period') }} AS s
  ) AS u
  GROUP BY
    u.segment_type,
    u.segment_name,
    u.retail_year,
    u.period
) AS g
